//! Windows keyboard hook. The pure helpers compile on every target so their tests run on Linux.
#[cfg(windows)]
pub mod clipboard;
#[cfg(windows)]
pub mod hook;
#[cfg(windows)]
pub mod paste;
#[cfg(windows)]
pub use hook::{start_hook, HookHandle};

/// KBDLLHOOKSTRUCT.flags: the event was generated by SendInput, not a keyboard.
const LLKHF_INJECTED: u32 = 0x10;
/// Scan code of the LCtrl that Windows sends just before RAlt on AltGr layouts.
const ALTGR_FAKE_CTRL_SCAN: u32 = 0x21D;

pub fn is_injected(flags: u32) -> bool {
    flags & LLKHF_INJECTED != 0
}

pub fn is_altgr_fake_ctrl(vk: u16, scan_code: u32) -> bool {
    vk == 0xA2 && scan_code == ALTGR_FAKE_CTRL_SCAN
}

/// Windows drops a low-level hook silently, so the hook thread re-installs it while this is true.
/// Re-hooking mid-dictation or with a key down could lose that key's up event.
pub fn can_rehook(idle: bool, is_down: &dyn Fn(u16) -> bool) -> bool {
    idle && !(1..=254).any(is_down)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rehook_only_when_idle_and_no_key_down() {
        let none_down = |_: u16| false;
        assert!(can_rehook(true, &none_down));
        assert!(!can_rehook(false, &none_down));
        assert!(!can_rehook(true, &|vk| vk == 0x41));
        assert!(!can_rehook(false, &|vk| vk == 0x41));
    }

    #[test]
    fn injected_flag() {
        assert!(is_injected(0x10));
        assert!(!is_injected(0x01));
    }

    #[test]
    fn altgr_fake_ctrl_only_for_scan_21d() {
        assert!(is_altgr_fake_ctrl(0xA2, 0x21D));
        assert!(!is_altgr_fake_ctrl(0xA2, 0x1D));
        assert!(!is_altgr_fake_ctrl(0xA3, 0x21D));
    }
}
